window.kbPageData["views/entry/k-e2c5925504cbae0f"] = {"key":"entry/k-e2c5925504cbae0f","state":{"route":"entry/k-e2c5925504cbae0f"},"node":{"id":"k-e2c5925504cbae0f","mode":"k","title":"“三北”工程攻坚战","type":"事实与事件","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["ecology"],"主类":["事实与事件"],"出处性质":["机构注释"],"学科":["生态环境"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"directorySummary":"5.“三北”工程攻坚战\n（1）“三北”工程：\n三北防护林工程，是我国在三北地区（西北、华北、东北）建设的大型人工林业生态工\n程。“三北”工程规划从 1978 年开始到 2050 年结束，历时 73 年，分三个阶段、八期工程\n进行建设。\n（2）“三北”工程攻坚战\n2021－2030 年是“三北”工程六…","sources":[{"id":"a2985415f3934ea2","label":"“三北”工程攻坚战","topic":"年度政府工作","category":"时政","text":"5.“三北”工程攻坚战\n（1）“三北”工程：\n三北防护林工程，是我国在三北地区（西北、华北、东北）建设的大型人工林业生态工\n程。“三北”工程规划从 1978 年开始到 2050 年结束，历时 73 年，分三个阶段、八期工程\n进行建设。\n（2）“三北”工程攻坚战\n2021－2030 年是“三北”工程六期工程建设期，是巩固拓展防沙治沙成果的关键期，\n是推动“三北”工程高质量发展的攻坚期。要完整、准确、全面贯彻新发展理念，坚持山水\n林田湖草沙一体化保护和系统治理，以防沙治沙为主攻方向，以筑牢北方生态安全屏障为根\n本目标，因地制宜、因害设防、分类施策，加强统筹协调，突出重点治理，调动各方面积极\n性，力争用 10 年左右时间，打一场“三北”工程攻坚战，把“三北”工程建设成为功能完\n备、牢不可破的北疆绿色长城、生态安全屏障。\n要突出治理重点，全力打好三大标志性战役：要全力打好黄河“几字弯”攻坚战。要全\n力打好科尔沁、浑善达克两大沙地歼灭战。要全力打好河西走廊－塔克拉玛干沙漠边缘阻击\n战。\n——习近平在加强荒漠化综合防治和推进“三北”等重点生态工程建设座谈会上的讲话","source":{"doc":"6cbfb01fe723bba64b75","first":46,"last":47,"page":46,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"ecology","title":"生态保护与绿色转型"}],"units":{"k-e2c5925504cbae0f":[]}};
